#!/usr/bin/env python3
# Flugfunk auf /adsb. Kein Mesh. prepper-sdr wird nicht neu gestartet.
from __future__ import annotations
import base64, hashlib, json, os, shutil, sys
from datetime import datetime
from pathlib import Path

DASH = Path("/home/fmg/prepper-dashboard")
DATEIEN = ("dashboard.py", "flugfunk.py")
FEST = {
    "flugfunk.py": ("90dc0c4b05f7dac4", 57095),
    "prepper_sdr.py": ("9519012e7a1142ba", 779574),
}
PAKETE = """===== SCHRITT PAKETE, dieses Skript installiert nichts =====
rtl_airband bleibt /usr/local/bin/rtl_airband (Quellbau, -DSOAPYSDR=OFF -DPULSEAUDIO=OFF).
whisper.cpp und ggml-base.en.bin wie bisher.
===== ENDE SCHRITT PAKETE ====="""

def load():
    return json.loads(PAYLOAD_TEXT)

def sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()

def fenster(now=None):
    from zoneinfo import ZoneInfo
    jetzt = now or datetime.now(ZoneInfo("Europe/Berlin"))
    return 5 <= jetzt.minute <= 39, "Berlin Minute %02d" % jetzt.minute

def paare():
    roh = load()["pairs"]
    return {name: [(base64.b64decode(x["old"]), base64.b64decode(x["new"])) for x in roh[name]] for name in DATEIEN}

def verwandle(data, pairs):
    neu = data
    for old, neu_s in pairs:
        if neu.count(neu_s) >= 1 and neu.count(old) == 0:
            continue
        if neu.count(old) != 1 or neu.count(neu_s) != 0 or old in neu_s:
            raise RuntimeError("Stelle")
        vor = neu
        neu = neu.replace(old, neu_s, 1)
        if neu.replace(neu_s, b"", 1) != vor.replace(old, b"", 1):
            raise RuntimeError("ausserhalb")
    return neu

def sichern(path: Path, data: bytes):
    stempel = datetime.now().astimezone().strftime("%Y%m%dT%H%M%S")
    alt = sorted(path.parent.glob(path.name + ".bak-flugfunk3-*"))
    bak = path.with_name(path.name + ".bak-flugfunk3-" + stempel)
    shutil.copy2(path, bak)
    if bak.read_bytes() != data:
        bak.unlink()
        raise RuntimeError("Sicherung")
    for alt_pfad in alt[:-2]:
        try:
            alt_pfad.unlink()
        except OSError:
            pass

def schreiben(path: Path, data: bytes):
    mode = path.stat().st_mode & 0o777
    tmp = path.with_name("." + path.name + ".tmp-flugfunk3")
    if tmp.exists():
        raise RuntimeError("temporaer")
    try:
        with open(tmp, "wb") as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(tmp, mode)
        os.replace(tmp, path)
    finally:
        if tmp.exists():
            try:
                tmp.unlink()
            except OSError:
                pass

def apply_dir(ordner: Path, dry: bool, kein: bool, jetzt=None, hashcheck=True) -> int:
    print(PAKETE)
    liste = paare()
    blobs = {}
    for name in ("flugfunk.py", "prepper_sdr.py", "dashboard.py"):
        pfad = ordner / name
        if name == "prepper_sdr.py" and (not pfad.is_file() or pfad.is_symlink()):
            if hashcheck:
                print("STOP: prepper_sdr.py fehlt")
                return 2
            continue
        if pfad.is_symlink() or not pfad.is_file():
            print("STOP: %s fehlt" % name)
            return 2
        data = pfad.read_bytes()
        blobs[name] = data
        print("%s sha16 %s bytes %d" % (name, sha(data)[:16], len(data)))
        if hashcheck and name in FEST:
            kopf, laenge = FEST[name]
            if not sha(data).startswith(kopf) or len(data) != laenge:
                print("STOP: %s ist nicht der Stand nach apply-flugfunk-2" % name)
                return 2
    try:
        ziel = {name: verwandle(blobs[name], liste[name]) for name in DATEIEN}
    except RuntimeError:
        print("STOP: Stelle unbekannt")
        return 2
    if hashcheck:
        for name, data in ziel.items():
            compile(data, name, "exec")
    if b'"/adsb"' not in ziel["dashboard.py"] or b'funk_seite(body, "/funk")' not in ziel["dashboard.py"]:
        print("STOP: Seite nicht verschoben")
        return 2
    if b"def deutsch" not in ziel["flugfunk.py"] or b"ffKarte" not in ziel["flugfunk.py"]:
        print("STOP: Ausbau fehlt")
        return 2
    print("dashboard.py endstand sha16 %s bytes %d" % (sha(ziel["dashboard.py"])[:16], len(ziel["dashboard.py"])))
    print("flugfunk.py endstand sha16 %s bytes %d" % (sha(ziel["flugfunk.py"])[:16], len(ziel["flugfunk.py"])))
    if "prepper_sdr.py" in blobs:
        print("prepper_sdr.py unveraendert sha16 %s" % sha(blobs["prepper_sdr.py"])[:16])
    if all(blobs[name] == ziel[name] for name in DATEIEN):
        print("bereits installiert, keine Aenderung, kein Neustart")
        return 0
    frei, meldung = fenster(jetzt)
    print(meldung)
    if dry:
        print("DRY-RUN: kein Backup, kein Schreiben, kein Neustart")
        print("Pruefung: curl -sS http://127.0.0.1:5000/adsb | grep -c flugfunkBox")
        return 0
    if not frei:
        print("STOP: Neustart nur Minute 05-39 Berlin. Nichts geschrieben.")
        return 2
    try:
        for name in DATEIEN:
            sichern(ordner / name, blobs[name])
            schreiben(ordner / name, ziel[name])
    except (OSError, RuntimeError):
        print("STOP beim Schreiben")
        return 3
    print("geschrieben. Kachel auf /adsb. prepper-sdr bleibt laufen.")
    if kein or ordner != DASH:
        print("Kein Neustart in dieser Pruefung.")
        return 0
    frei, meldung = fenster()
    print(meldung)
    if not frei:
        print("STOP: Dateien sind neu, der Neustart bleibt aus.")
        return 2
    __import__("subprocess").run(["systemctl", "restart", "prepper-dashboard.service"], check=False)
    print("Nur prepper-dashboard neu gestartet.")
    return 0

def selftest() -> int:
    assert fenster(datetime(2026, 11, 21, 12, 5))[0] and fenster(datetime(2026, 11, 21, 12, 39))[0]
    assert not fenster(datetime(2026, 11, 21, 12, 4))[0] and not fenster(datetime(2026, 11, 21, 12, 40))[0]
    import tempfile
    liste = paare()
    ordner = Path(tempfile.mkdtemp(prefix="flugfunk3-"))
    for name in DATEIEN:
        (ordner / name).write_bytes(b"UNBERUEHRT")
    assert apply_dir(ordner, True, True, datetime(2026, 11, 21, 12, 12), False) == 2
    assert (ordner / "dashboard.py").read_bytes() == b"UNBERUEHRT"
    for name, pairs in liste.items():
        blob = b"\n".join(old for old, _neu in pairs)
        (ordner / name).write_bytes(blob)
    assert apply_dir(ordner, False, True, datetime(2026, 11, 21, 12, 4), False) == 2
    assert apply_dir(ordner, False, True, datetime(2026, 11, 21, 12, 12), False) == 0
    assert b'"/adsb"' in (ordner / "dashboard.py").read_bytes()
    roh = base64.b64decode(load()["flugfunk_neu"])
    ns = {"__name__": "flugfunk"}
    exec(compile(roh, "flugfunk.py", "exec"), ns)
    adsb = ns["funk_seite"]("<html><body><p>alt</p></body></html>", "/adsb")
    funk = ns["funk_seite"](adsb, "/funk")
    assert adsb.count('id="flugfunkBox"') == 1 and "ffKarte" in adsb and "ffPush" in adsb
    assert 'id="flugfunkBox"' not in funk
    de, en = ns["deutsch"]("cleared ils runway 28")
    assert "ILS-Freigabe" in de and "Piste" in de and "cleared" in en
    print("selftest ok")
    return 0

def main(argv):
    args = argv[1:]
    dry = kein = False
    wurzel = DASH
    i = 0
    while i < len(args):
        a = args[i]
        if a == "--dry-run":
            dry = True
        elif a == "--kein-neustart":
            kein = True
        elif a == "--selftest":
            return selftest()
        elif a == "--wurzel":
            i += 1
            wurzel = Path(args[i])
        else:
            print("STOP: unbekanntes Argument")
            return 2
        i += 1
    return apply_dir(wurzel, dry, kein)

